function h(text, level) { return new Paragraph({ text, heading: level, spacing: { before: 240, after: 120 } }); }
function p(text, opts = {}) { return new Paragraph({ children: [new TextRun({ text, ...opts })], spacing: { after: 160 } }); }
function pRuns(runs, opts = {}) { return new Paragraph({ children: runs, spacing: { after: 160 }, ...opts }); }
function bullet(text) { return new Paragraph({ text, bullet: { level: 0 }, spacing: { after: 80 } }); }
function caption(text) {
  return new Paragraph({ children: [new TextRun({ text, bold: true, size: 20 })],
    spacing: { before: 80, after: 240 }, alignment: AlignmentType.CENTER });
}
function img(file, wIn, hIn) {
  const buf = fs.readFileSync(path.join(RES, file));
  return new Paragraph({ children: [new ImageRun({ type: "png", data: buf, transformation: { width: wIn * 96, height: hIn * 96 } })],
    alignment: AlignmentType.CENTER, spacing: { before: 160, after: 40 } });
}
function cell(text, opts = {}) {
  return new TableCell({
    width: { size: opts.width || 1200, type: WidthType.DXA },
    shading: opts.header ? { type: ShadingType.CLEAR, fill: "1F4E79" } : undefined,
    children: [new Paragraph({
      children: [new TextRun({ text: String(text), bold: !!opts.header, color: opts.header ? "FFFFFF" : "000000", size: 16 })],
      alignment: opts.center === false ? AlignmentType.LEFT : AlignmentType.CENTER })],
    verticalAlign: "center",
  });
}
function dataTable(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  return new Table({
    width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    rows: [
      new TableRow({ children: headers.map((hd, i) => cell(hd, { header: true, width: widths[i] })) }),
      ...rows.map(r => new TableRow({ children: r.map((c, i) => cell(c, { width: widths[i], center: true })) })),
    ],
  });
}

